mapper.sql:
WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})


        AND credit_memos.status = #{filter.status}


        AND credit_memos.status > 0


AND location_group_id IN (SELECT location_group_id FROM user_location_groups WHERE user_id = #{userId})

    AND (
        credit_memos.cm_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND credit_memos.order_date >= #{filter.dateFrom}


    AND credit_memos.order_date <= #{filter.dateTo}


    AND credit_memos.created_by = #{filter.createdBy}


    AND credit_memos.company_id = #{filter.companyId}


    AND credit_memos.location_group_id = #{filter.warehouseId}


    AND credit_memos.customer_id = #{filter.organizationId}


    AND credit_memos.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})

mapper.select:
SELECT credit_memos.id AS id, credit_memos.order_date AS cmDate, credit_memos.cm_code AS cmNo, credit_memos.invoice_code AS invoiceCode, CONCAT_WS(' ', customers.name) AS organizationName, credit_memos.total_amount-IFNULL(credit_memos.discount,0) AS subTotal, IFNULL(credit_memos.total_vat,0) AS totalVat, credit_memos.total_amount-IFNULL(credit_memos.discount,0)+IFNULL(credit_memos.mark_up,0)+IFNULL(credit_memos.total_vat,0) AS totalAmount, credit_memos.balance AS balance, IF(balance>0 AND DATEDIFF(now(),due_date)>0,DATEDIFF(now(),due_date),'.') AS aging, credit_memos.status AS status, currency_centers.symbol AS currencySymbol FROM credit_memos LEFT JOIN customers ON customers.id = credit_memos.customer_id INNER JOIN currency_centers ON currency_centers.id = credit_memos.currency_center_id
ORDER BY credit_memos.order_date DESC, credit_memos.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}
